function findGeneRepeats(s: string): string[] {
  const out = new Set<string>();
  for (let i = 0; i + 10 <= s.length; i++) {
    const w = s.slice(i, i + 10);
    if (out.has(w)) continue;
    for (let j = i + 1; j + 10 <= s.length; j++) {
      if (s.startsWith(w, j)) { out.add(w); break; }
    }
  }
  return [...out];
}

