function findGeneRepeats(s: string): string[] {
  const code: Record<string, number> = { A: 0, C: 1, G: 2, T: 3 };
  const mask = (1 << 20) - 1;
  const count = new Uint8Array(1 << 20);
  const out: string[] = [];
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 2) | code[s[i]]) & mask;
    if (i < 9) continue;
    if (count[h] === 1) out.push(s.slice(i - 9, i + 1));
    if (count[h] < 2) count[h]++;
  }
  return out;
}

