        code = {"A": 0, "C": 1, "G": 2, "T": 3}
        mask = (1 << 20) - 1
        count = {}
        out = []
        h = 0
        for i, ch in enumerate(s):
            h = ((h << 2) | code[ch]) & mask
            if i < 9:
                continue
            c = count.get(h, 0)
            if c == 1:
                out.append(s[i - 9:i + 1])
            count[h] = c + 1
        return out

